import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for a, i in at[r]:
                heapq.heappush(heap, (-a, i))

            top = -heap[0][0] if heap else 0
            base += r - top

            if heap:
                a, i = heap[0]
                second = -heap[1][0] if len(heap) > 1 else 0
                if -a > second:
                    gains[i] += -a - second

        return base + max(gains)

