import sys
from collections import deque

def solve():
    data=sys.stdin.read().split()
    n=int(data[0]); rows=data[1:]
    inc=[[0]*26 for _ in range(n)]
    out=[[0]*26 for _ in range(n)]
    for i,row in enumerate(rows):
        for j,ch in enumerate(row):
            if ch!='-':
                c=ord(ch)-97
                out[i][c] |= 1<<j
                inc[j][c] |= 1<<i
    d=[[-1]*n for _ in range(n)]
    seen=[0]*n
    q=deque()
    for i in range(n):
        d[i][i]=0; seen[i]|=1<<i; q.append((i,i))
    for i in range(n):
        for j in range(n):
            if rows[i][j]!='-' and d[i][j]<0:
                d[i][j]=1; seen[i]|=1<<j; q.append((i,j))
    while q:
        u,v=q.popleft()
        nd=d[u][v]+2
        for c in range(26):
            xs=inc[u][c]; ys=out[v][c]
            while xs:
                b=xs & -xs; xs-=b
                x=b.bit_length()-1
                mask=ys & ~seen[x]
                while mask:
                    by=mask & -mask; mask-=by
                    y=by.bit_length()-1
                    seen[x] |= by
                    d[x][y]=nd; q.append((x,y))
    print('\n'.join(' '.join(map(str,r)) for r in d))

